import * as React from "react"
import { useEffect, useState } from "react"
import "../styles/inProgress.css"

const NotFoundPage = () => {
  const [map, setMap] = useState(null)

  useEffect(() => {
    // Only run in browser
    if (typeof window === "undefined") return

    // Dynamically import Leaflet (THIS is the key fix)
    import("leaflet").then((L) => {
      require("leaflet/dist/leaflet.css")

      const mapInstance = L.map("map").setView([33.7765, -84.3967], 15)

      L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
        attribution: "&copy; OpenStreetMap contributors",
      }).addTo(mapInstance)

      // Default marker
      L.marker([33.7765, -84.3967])
        .addTo(mapInstance)
        .bindPopup("Georgia Tech")
        .openPopup()

      // Click to add markers
      mapInstance.on("click", function (e) {
        L.marker([e.latlng.lat, e.latlng.lng])
          .addTo(mapInstance)
          .bindPopup("New Emotion")
          .openPopup()
      })

      setMap(mapInstance)
    })
  }, [])

  return (
    <main className="pageStyles">
      <h1 className="headingStyles">Buzzing Emotions</h1>
      <div id="map" className="mapContainer"></div>
    </main>
  )
}

export default NotFoundPage